# Change a claim's status: open (DRAFT -> OPEN), settle (OPEN -> SETTLED), approve (PENDING -> SETTLED),
# reject (PENDING -> OPEN, with the body's reason) or void (DRAFT, OPEN or PENDING -> VOID).
# A change its status does not allow is refused (400) and writes nothing.
# A claim dated inside a closed period is refused (400).
# A clerk settling a claim whose due is above the sheet's clerk limit makes it PENDING; a steward settles anything.
# Only a steward approves or rejects; the user who opened the claim cannot approve it.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimActionRequest
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkPeriod
checkPeriod:
  class: net.officefloor.hq.app.claim.CheckClaimPeriodOpen
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimAction
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimAction
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Edit a claim's amount, date and note; refused (400) on the same terms as an add.
# Only a DRAFT claim can be edited; any other is refused (400).
# A claim dated (before or after the edit) inside a closed period is refused (400).
# A claim edited to a date after its person's retirement date is refused (400).
# A correction is refused (400) on the same terms as an add.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimRequest
  next: load
