  class: net.officefloor.hq.app.claim.CheckClaimPeriodOpen
  govern: [ transaction ]
  next: checkNewPeriod
checkNewPeriod:
  class: net.officefloor.hq.app.claim.CheckClaimInputPeriodOpen
  govern: [ transaction ]
