# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (id order, descending).
CREATE TABLE claim (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    amount DECIMAL(15, 2) NOT NULL,
    claim_date DATE NOT NULL,
    note VARCHAR(1000) NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- A person's statement records their due-total at that moment and binds each of their counting
-- claims to the figure it has then. The person keeps how many statements were taken, the last one's
-- due-total ('n/a' when it had none) and the sheet's today when it was taken.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A stated claim shows and totals its bound figure (stated_due; null: n/a) until its person's next
-- statement rebinds it, or unbinds it (live again) when it no longer counts.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(25, 2);
-- The sheet's period numbering from date: while it is set and the sheet's today is on or after it, an opened
-- claim is numbered within its period (<period name>-<n>; X-<n> for a claim in no period); null: off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number (and the number a correction names) is now text: a sheet-wide 1, 2, ... or a per-period P1-1, X-1.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);
-- The last number each per-period sequence gave out: seq_key is the period's name in lower case, or '' for
-- the claims in no period (X). A number taken is never given out again.
CREATE TABLE period_claim_number (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    seq_key VARCHAR(100) NOT NULL,
    last_number INT NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
package net.officefloor.hq.app.rollup;

import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Follows a change's own records with one ROLLUP line per person whose figures it moved (a person new to the
 * sheet counts as moved), in the order they were added, then a TOTALS line when the sheet's totals moved.
 */
public class AuditRollup {
    public void audit(@Val RollupBefore before, @PathVariable("sheetId") String sheetId,
            @RequestParam("user") String user, RollupService rollups, Audit audit) {
        Rollup was = before.rollup();
        Rollup now = rollups.compute(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
            Rollup.Figures figures = entry.getValue();
            if (!figures.sameAs(was.people().get(entry.getKey()))) {
                audit.record("ROLLUP" + prefix + " person=" + figures.name() + " claimed=" + figures.claimed()
                        + " due-total=" + figures.dueTotal());
            }
        }
        if (!now.claimedTotal().equals(was.claimedTotal()) || !now.dueTotal().equals(was.dueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + now.claimedTotal() + " due-total="
                    + now.dueTotal());
        }
    }
}
package net.officefloor.hq.app.rollup;

/** The sheet's figures taken before a change, to tell afterwards which of them it moved. */
public record RollupBefore(Rollup rollup) {
}
package net.officefloor.hq.app.rollup;

import java.util.Map;

/**
 * A sheet's figures at one moment: each person's claimed and due-total (by person id, in the order they were
 * added) and the sheet's claimed-total and due-total, each as shown (two decimals; a due-total may be n/a).
 */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {

    /** A person's name and figures. */
    public record Figures(String name, String claimed, String dueTotal) {

        /** Whether the figures are the same as the other's, whatever the name. */
        public boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
        }
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
 * added up; their due-total those claims' dues (live figures raised to the sheet's floor and rounded by its policy date, plus
 * any late charge on the overdue ones) added up, n/a when their grade on the sheet's today has no
 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). The sheet's totals add these up, skipping n/a.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup compute(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.findAll(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean kept = false;
            for (Claim claim : sheetClaims) {
                if (claim.personId() != person.id() || !person.counts(claim)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                kept |= claim.keepsFigure();
                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()), floor, late, rounding);
                if (figure != null) {
                    kept = true;
                    due = due.add(figure);
                }
            }
            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due)));
        }
        return new Rollup(figures, show(claimedTotal), show(dueTotal));
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
